import json

def extract_ticket_fields(raw_model_output):
    cleaned = raw_model_output.strip()
    if cleaned.startswith("```"):
        cleaned = cleaned.strip("`").removeprefix("json").strip()
    return json.loads(cleaned)

def test_extract_ticket_fields_strips_markdown_fence():
    raw = '```json\n{"priority": "high", "category": "billing"}\n```'
    result = extract_ticket_fields(raw)
    assert result == {"priority": "high", "category": "billing"}

def test_extract_ticket_fields_raises_on_garbage():
    import pytest
    with pytest.raises(json.JSONDecodeError):
        extract_ticket_fields("not json at all")

def check_summary(summary, required_entities, forbidden_terms, min_words=20, max_words=80):
    word_count = len(summary.split())
    checks = {
        "length_in_range": min_words <= word_count <= max_words,
        "mentions_required_entities": all(e.lower() in summary.lower() for e in required_entities),
        "no_forbidden_terms": not any(t.lower() in summary.lower() for t in forbidden_terms),
    }
    return checks, all(checks.values())

checks, passed = check_summary(
    summarize(article),
    required_entities=["renewable energy", "policy"],
    forbidden_terms=["guaranteed", "risk-free"],
)
