def run_eval(examples, generate_fn):
    results = []
    for ex in examples:
        output = generate_fn(ex["input"])
        passed = ex["grade_fn"](output, ex)
        results.append((ex["category"], passed))

    overall = sum(passed for _, passed in results) / len(results)

    by_category_lists = {}
    for category, passed in results:
        by_category_lists.setdefault(category, []).append(passed)
    by_category = {cat: sum(v) / len(v) for cat, v in by_category_lists.items()}

    return {"overall": overall, "by_category": by_category}

