def build_judge_prompt(question, response, rubric_criteria, reference_answer=None):
    rubric_lines = "\n".join(f"{i}. {criterion}" for i, criterion in enumerate(rubric_criteria, start=1))
    reference_section = f"\nREFERENCE_ANSWER: {reference_answer}" if reference_answer is not None else ""

    return (
        f"Evaluate the RESPONSE to the QUESTION using this rubric:\n{rubric_lines}\n\n"
        f"QUESTION: {question}{reference_section}\nRESPONSE: {response}\n\n"
        "Return JSON with keys 'reasoning' (a string explaining your assessment against "
        "each rubric item) and 'score' (an integer from 1 to 5)."
    )
